insert into ref.transects (id, river_id, name, transect_code, display_name, range, transect_order, remark, canton,
                           start_lat, start_lon, end_lat, end_lon, mid_lat, mid_lon, geom_wgs84, geom_lv95)
overriding system value
select case g.code when 'ZZ01' then 59 else 60 end, r.id, g.name, g.code, g.dn, '', 1, g.remark, g.canton,
       st_y(st_startpoint(g.geom)), st_x(st_startpoint(g.geom)), st_y(st_endpoint(g.geom)), st_x(st_endpoint(g.geom)),
       st_y(st_lineinterpolatepoint(g.geom, 0.5)), st_x(st_lineinterpolatepoint(g.geom, 0.5)),
       g.geom, st_transform(g.geom, 2056)
from g join ref.rivers r on r.code = g.rc;

update ref.rivers r set geom_wgs84 = st_multi(t.geom_wgs84), geom_lv95 = st_multi(t.geom_lv95)
from ref.transects t where t.river_id = r.id and r.id in (5, 6);

select setval(pg_get_serial_sequence('ref.rivers','id'), (select max(id) from ref.rivers));
select setval(pg_get_serial_sequence('ref.transects','id'), (select max(id) from ref.transects));

comment on column ref.transects.remark is 'Free-text note, e.g. meaning of the code prefix';
comment on column ref.transects.canton is 'Swiss canton code (GR, TI, ...)';
